	int xp, yp, vp, xs, ys, V, R;

	cin >> xp;
	cin >> yp;
	cin >> vp;
	cin >> xs;
	cin >> ys;
	cin >> V;
	cin >> R;

	Point ini_perse(xp, yp);
	Point perse(0, 0);
	Point center(0, 0);
	Point ship(xs, ys);

	long double time = 0;
	long double time_ship = 0;
	long double range_min, range_max;

	if (ini_perse.x == ship.x && ini_perse.y == ship.y)
	{
		cout << time;
		return 0;
	}

	time = 100;

	while (true)
	{
		pos_circle(ini_perse, vp, time, &perse);
		Segment s(perse, ship);
		long double distance = distance_to_segment(center, s);

		if (distance >= R)
		{
			time_ship = s.length() / V;
		}
		else
		{
			Point ship_tang1, ship_tang2, perse_tang1, perse_tang2;
			tangent_points_to_circle(center, R, ship, &ship_tang1, &ship_tang2);
			tangent_points_to_circle(center, R, perse, &perse_tang1, &perse_tang2);

			Segment route1_ship(ship, ship_tang1);
			Segment route2_ship(ship, ship_tang2);
			Segment route1_perse(perse_tang2, perse);
			Segment route2_perse(perse_tang1, perse);

			long double distance1 =
				route1_ship.length() +
				fabs(atan2(ship_tang1.y, ship_tang1.x) -
				     atan2(perse_tang2.y, perse_tang2.x)) * 2 * R +
				route1_perse.length();

			long double distance2 =
				route2_ship.length() +
				fabs(atan2(ship_tang2.y, ship_tang2.x) -
				     atan2(perse_tang1.y, perse_tang1.x)) * 2 * R +
				route2_perse.length();

			time_ship = min(distance1, distance2) / V;
		}

		if (time_ship < time)
			break;

		time *= 2;
	}

	range_max = time;
	range_min = 0;

	while (true)
	{
		time = (range_max + range_min) / 2;
		pos_circle(ini_perse, vp, time, &perse);

		Segment s(perse, ship);
		long double distance = distance_to_segment(center, s);

		if (distance >= R)
		{
			time_ship = s.length() / V;
		}
		else
		{
			Point ship_tang1, ship_tang2, perse_tang1, perse_tang2;
			tangent_points_to_circle(center, R, ship, &ship_tang1, &ship_tang2);
			tangent_points_to_circle(center, R, perse, &perse_tang1, &perse_tang2);

			Segment route1_ship(ship, ship_tang1);
			Segment route2_ship(ship, ship_tang2);
			Segment route1_perse(perse_tang2, perse);
			Segment route2_perse(perse_tang1, perse);

			long double distance1 =
				route1_ship.length() +
				fabs(atan2(ship_tang1.y, ship_tang1.x) -
				     atan2(perse_tang2.y, perse_tang2.x)) * R +
				route1_perse.length();

