				route2_ship.length() +
				fabs(atan2(ship_tang2.y, ship_tang2.x) -
				     atan2(perse_tang1.y, perse_tang1.x)) * R +
				route2_perse.length();

			time_ship = min(distance1, distance2) / V;
		}

		if (fabs(time - time_ship) < 0.0000000001L)
			break;

		if (time_ship < time)
			range_max = time;
		else
			range_min = time;
	}

	cout << time;
	return 0;
}

